        hu: ["Szobor: 5 méter hosszú fekvő Visnu-szobor.", "Anyag: Egyetlen fekete bazalttömb.", "Kor: Feltehetően a 7. századból (Licchavi-korszak).", "Helyszín: A Shivapuri-hegy lábánál, Katmandu.", "Medence: A szobor egy 13 méter hosszú vizes medencében fekszik.", "Név: Jelentése 'Öreg kék torok', bár Visnut ábrázol.", "Királyi tilalom: A nepáli királyoknak tilos volt meglátogatniuk.", "Fesztiválok: A Haribodhini Ekadashi fontos központja."],
        ro: ["Statuie: Statuie culcată de 5 metri a lui Vishnu.", "Material: Un singur bloc de piatră de bazalt negru.", "Vârstă: Probabil din secolul al VII-lea (perioada Licchavi).", "Locație: La poalele dealului Shivapuri, Kathmandu.", "Bazin: Statuia se află într-un bazin de apă de 13 metri lungime.", "Nume: Înseamnă 'Gâtul Albastru Bătrân', deși îl înfățișează pe Vishnu.", "Interdicție regală: Regilor nepalezi le era interzis să o viziteze.", "Festivaluri: Centru important pentru Haribodhini Ekadashi."],
        en: ["Statue: 5-meter long reclining statue of Vishnu.", "Material: Single block of black basalt stone.", "Age: Presumably from the 7th century (Licchavi period).", "Location: At the foot of the Shivapuri Hill, Kathmandu.", "Pool: The statue lies in a 13-meter long pool of water.", "Name: Means 'Old Blue Throat', although it depicts Vishnu.", "Royal Prohibition: Nepalese kings were forbidden to visit.", "Festivals: Important center for Haribodhini Ekadashi."],
        es: ["Estatua: Imagen reclinada de Vishnu de 5 metros de largo.", "Material: Bloque único de piedra de basalto negro.", "Antigüedad: Probablemente del siglo VII (periodo Licchavi).", "Ubicación: Al pie de la colina Shivapuri, Katmandú.", "Estanque: La estatua yace en un estanque de agua de 13 metros de largo.", "Nombre: Significa 'Vieja garganta azul', aunque representa a Vishnu.", "Prohibición real: Los reyes nepaleses tenían prohibida la visita.", "Festivales: Centro importante para Haribodhini Ekadashi."],
        pt: ["Estátua: Estátua reclinada de Vishnu com 5 metros de comprimento.", "Material: Bloco único de pedra de basalto negro.", "Idade: Provavelmente do século VII (período Licchavi).", "Localização: No sopé da colina Shivapuri, Kathmandu.", "Tanque: A estátua repousa num tanque de água de 13 metros de comprimento.", "Nome: Significa 'Velha garganta azul', embora represente Vishnu.", "Proibição Real: Os reis nepaleses eram proibidos de visitar.", "Festivais: Centro importante para Haribodhini Ekadashi."],
        fr: ["Statue : Statue inclinée de Vishnu de 5 mètres de long.", "Matériau : Bloc unique de pierre de basalte noir.", "Âge : Probablement du VIIe siècle (période Licchavi).", "Localisation : Au pied de la colline de Shivapuri, Katmandou.", "Bassin : La statue repose dans un bassin d'eau de 13 mètres de long.", "Nom : Signifie « Vieille gorge bleue », bien qu'elle représente Vishnu.", "Interdiction royale : La visite était interdite aux rois népalais.", "Festivals : Centre important pour Haribodhini Ekadashi."],
